"use client"; // Required for hooks in Next.js

import { useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation"; // Use this instead of react-router-dom
import Link from "next/link"; // Use this instead of react-router-dom

const Signup = () => {
    // 1. Initialize state with empty strings to avoid 'undefined' errors
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    
    // 2. Switch to the Next.js router
    const router = useRouter();

    const handleSubmit = (e) => {
        e.preventDefault();

        // Basic validation
        if (password !== confirmPassword) {
            alert("Passwords do not match");
            return;
        }

        axios.post('http://localhost:5000/register', { name, email, password })
            .then(result => {
                console.log(result);
                // 3. Use router.push instead of navigate
                router.push('/login'); 
            })
            .catch(error => console.error(error));
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-100">
            <form className="bg-white p-8 rounded-2xl shadow-lg w-96" onSubmit={handleSubmit}>
                <h2 className="text-2xl font-bold mb-6 text-center">Create Account</h2>
                
                {/* Name Input */}
                <div className="mb-4">
                    <label className="block mb-1 text-sm font-medium">Full Name</label>
                    <input
                        type="text"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setName(e.target.value)}
                        required
                    />
                </div>
               <div className="mb-4">
                    <label className="block mb-1 text-sm font-medium">Email</label>
                    <input
                        type="email"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setEmail(e.target.value)}
                        required
                    />
                </div>
                <div className="mb-4">
                    <label className="block mb-1 text-sm font-medium">Password</label>
                    <input
                        type="password"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setPassword(e.target.value)}
                        required
                    />
                </div>
                <div className="mb-4">
                    <label className="block mb-1 text-sm font-medium">Confirm Password</label>
                    <input
                        type="password"
                        className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        required
                    />
                </div>
                {/* Email, Password, and Confirm Password inputs follow the same pattern... */}

                <button type="submit" className="w-full bg-green-500 text-white py-2 rounded-lg hover:bg-green-600 transition">
                    Sign Up
                </button>
            </form>

            <p className="text-sm text-center mt-4">
                Already have an account?{" "}
                <Link href="/login" className="text-blue-500 hover:underline">
                    Login
                </Link>
            </p>
        </div>
    );
};

export default Signup;